 $foto=''; if(!empty($_FILES['foto']['name'])){ $ext=strtolower(pathinfo($_FILES['foto']['name'],PATHINFO_EXTENSION)); if(!in_array($ext,['jpg','jpeg','png','webp'])) $ext='jpg'; $name='cocina_'.time().'_'.rand(100,999).'.'.$ext; move_uploaded_file($_FILES['foto']['tmp_name'],__DIR__.'/../uploads/cocina/'.$name); $foto='uploads/cocina/'.$name; }
 $pdo->prepare('INSERT INTO cocina(id_usuario,tipo,titulo,descripcion,monto,foto,fecha) VALUES(?,?,?,?,?,?,?)')->execute([uid(),$_POST['tipo'],$_POST['titulo'],$_POST['descripcion'],$_POST['monto']?:0,$foto,$_POST['fecha']]); header('Location: listar.php'); exit;
}
if(isset($_GET['eliminar']) && es_admin()){ $pdo->prepare('UPDATE cocina SET eliminado=1 WHERE id_cocina=?')->execute([$_GET['eliminar']]); $pdo->prepare("INSERT INTO papelera(tabla,registro_id,accion,usuario) VALUES('cocina',?,'eliminado',?)")->execute([$_GET['eliminar'],$_SESSION['usuario']['email']]); header('Location: listar.php'); exit; }
